from chatterbot.adapters import Adapter
from chatterbot.storage import StorageAdapter
from chatterbot.search import IndexedTextSearch
from chatterbot.conversation import Statement
from collections.abc import Hashable
from chatterbot.logic import LogicAdapter

# Lớp Logic Adapter tùy chỉnh
class CustomLogicAdapter(LogicAdapter):
    def process(self, statement, additional_response_selection_parameters=None):
        # Logic tùy chỉnh để xử lý câu nói và trả về phản hồi
        response = Statement(text="Phản hồi tùy chỉnh")
        response.confidence = 1.0  # Confidence nằm trong khoảng từ 0 đến 1
        return response

# Lớp Logic Adapter trừu tượng
class LogicAdapter(Adapter):
    """ 
    Lớp trừu tượng cung cấp giao diện mà tất cả các logic adapter sẽ triển khai.

    :param search_algorithm_name: Tên của thuật toán tìm kiếm sẽ được sử dụng
        để tìm kiếm các câu phù hợp với đầu vào.
    :param maximum_similarity_threshold: Ngưỡng độ tương đồng tối đa giữa các câu nói.
        Mặc định là 0.95.
    :param response_selection_method: Phương thức chọn phản hồi.
    :param default_response: Phản hồi mặc định khi không có phản hồi khác phù hợp.
    """

    def __init__(self, chatbot, **kwargs):
        super().__init__(chatbot, **kwargs)
        from chatterbot.response_selection import get_first_response

        self.search_algorithm_name = kwargs.get(
            'search_algorithm_name',
            IndexedTextSearch.name
        )

        self.search_algorithm = self.chatbot.search_algorithms[
            self.search_algorithm_name
        ]

        self.maximum_similarity_threshold = kwargs.get(
            'maximum_similarity_threshold', 0.95
        )

        self.select_response = kwargs.get(
            'response_selection_method', 
            get_first_response
        )

        default_responses = kwargs.get('default_response', [])

        if isinstance(default_responses, str):
            default_responses = [default_responses]

        self.default_responses = [
            Statement(text=default) for default in default_responses
        ]

    def can_process(self, statement):
        """
        Kiểm tra sơ bộ xem bộ điều chỉnh có thể xử lý câu nói này không.
        Mặc định trả về True, có thể ghi đè trong các lớp con.
        """
        return True

    def process(self, statement, additional_response_selection_parameters=None):
        """
        Phương thức trừu tượng, yêu cầu bạn ghi đè nó trong lớp con để xử lý câu nói
        và chọn phản hồi.
        Trả về một đối tượng Statement với confidence (độ tin cậy).

        :param statement: Câu nói đầu vào.
        :type statement: Statement
        :param additional_response_selection_parameters: Các tham số bổ sung.
        :type additional_response_selection_parameters: dict
        :rtype: Statement
        """
        raise self.AdapterMethodNotImplementedError()

    def get_default_response(self, input_statement):
        """
        Phản hồi mặc định nếu bộ điều chỉnh không thể tìm thấy phản hồi nào thích hợp.
        """
        from random import choice

        if self.default_responses:
            response = choice(self.default_responses)
        else:
            try:
                response = self.chatbot.storage.get_random()
            except StorageAdapter.EmptyDatabaseException:
                response = input_statement

        self.chatbot.logger.info(
            'Không tìm thấy phản hồi. Chọn một phản hồi ngẫu nhiên.'
        )

        # Đặt confidence về 0 vì đây là phản hồi ngẫu nhiên
        response.confidence = 0

        return response

    @property
    def class_name(self):
        """
        Trả về tên lớp hiện tại của bộ điều chỉnh logic.
        Thường dùng cho mục đích ghi log và gỡ lỗi.
        """
        return str(self.__class__.__name__)
